'use strict';
const $=id=>document.getElementById(id);
const state={files:new Map(),scenes:new Map(),db:null,dbs:new Map(),dialogDb:null,dialogDirty:false,catalog:[],sceneName:null,sceneBytes:null,sceneDirty:false,fbsDirty:false,selected:null,view:null,viewer:null,enemyPreview:null,bsp:null,pak:null,externalPak:null,placeMode:null,pendingNewEnemy:null,pendingEnemyGroup:null,_counts:new Map(),undoByScene:new Map(),exeFile:null,exeBytes:null,customPools:ZEE.defaultCustomPools(),gameDirHandle:null,writeMeta:new Map(),canWriteGame:false};
function status(s){$('status').innerHTML=s}
function download(name,bytes){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function basename(p){return p.split(/[\\/]/).pop().toLowerCase()}

async function collectDirectoryFiles(root){
 const files=[],meta=new Map();
 async function walk(dir,prefix=''){
  for await(const [name,handle] of dir.entries()){
   const rel=prefix?prefix+'/'+name:name;
   if(handle.kind==='directory'){await walk(handle,rel);continue}
   const file=await handle.getFile();files.push(file);
   const key=basename(rel);if(key.endsWith('.scn')||key.endsWith('.bsp')||key.startsWith('_fb0x')||key==='data_0.pak'||key==='zanthp.exe')meta.set(key,{handle,parent:dir,path:rel,name});
  }
 }
 await walk(root);return{files,meta}
}
async function openGameFolder(){
 if(typeof window.showDirectoryPicker!=='function'){$('folder').click();return}
 try{
  const dir=await window.showDirectoryPicker({mode:'readwrite'});const scanned=await collectDirectoryFiles(dir);
  state.gameDirHandle=dir;state.writeMeta=scanned.meta;state.canWriteGame=true;
  await loadFolder(scanned.files,scanned.meta);
 }catch(e){if(e&&e.name==='AbortError')return;console.warn('Directory picker',e);$('folder').click()}
}
async function writeBytes(handle,bytes){const w=await handle.createWritable();await w.write(bytes);await w.close()}
async function ensureBackup(meta){
 if(!meta?.handle||!meta?.parent)return;
 const backupName=meta.name+'.zwe.bak';
 try{await meta.parent.getFileHandle(backupName);return}catch(e){if(e.name!=='NotFoundError')throw e}
 const src=await meta.handle.getFile(),dst=await meta.parent.getFileHandle(backupName,{create:true});await writeBytes(dst,new Uint8Array(await src.arrayBuffer()));
}
async function overwriteGameFiles(){
 try{
  if(!state.canWriteGame)throw new Error('Папка была открыта без права записи. Нажмите «Открыть папку игры» и разрешите доступ к папке.');
  if(!state.db)throw new Error('_fb0x05.fbs не загружен.');if(!state.sceneBytes||!state.sceneName)throw new Error('Сначала откройте сцену.');
  const fm=state.writeMeta.get('_fb0x05.fbs'),sm=state.writeMeta.get(state.sceneName.toLowerCase());
  if(!fm)throw new Error('Не найден путь исходного _fb0x05.fbs в выбранной папке игры.');if(!sm)throw new Error(`Не найден путь ${state.sceneName} в выбранной папке игры.`);
  if(!confirm(`Перезаписать файлы игры?\n\n${fm.path}\n${sm.path}\n\nПеред первой перезаписью рядом будут созданы резервные копии *.zwe.bak.`))return;
  await ensureBackup(fm);await ensureBackup(sm);
  const fbsBytes=ZEE.serializeDatabase(state.db);await writeBytes(fm.handle,fbsBytes);await writeBytes(sm.handle,state.sceneBytes);
  const fbsFile=await fm.handle.getFile(),scnFile=await sm.handle.getFile();state.files.set('_fb0x05.fbs',fbsFile);state.files.set(state.sceneName.toLowerCase(),scnFile);state.scenes.set(state.sceneName.toLowerCase(),scnFile);
  state.fbsDirty=false;state.sceneDirty=false;updateDebug();status(`Файлы перезаписаны прямо в игре: <b>${fm.path}</b> и <b>${sm.path}</b>. Резервные копии *.zwe.bak сохранены рядом с оригиналами.`);
 }catch(e){alert(e.message);console.error(e)}
}
async function loadFolder(list,writeMeta=null){
 state.files.clear();state.scenes.clear();state.dbs.clear();state.dialogDb=null;state.dialogDirty=false;
 if(writeMeta){state.writeMeta=writeMeta;state.canWriteGame=true}else{state.gameDirHandle=null;state.writeMeta=new Map();state.canWriteGame=false}
 const all=Array.from(list);
 // При выборе корня игры браузер отдаёт и вложенные файлы. Явно ищем Resources/data_0.pak,
 // чтобы пользователю не приходилось выбирать PAK отдельной кнопкой.
 const autoPak=all.find(f=>/[\\\/]resources[\\\/]data_0\.pak$/i.test(f.webkitRelativePath||f.name))||all.find(f=>basename(f.webkitRelativePath||f.name)==='data_0.pak');
 for(const f of all){const name=basename(f.webkitRelativePath||f.name);if(name.endsWith('.scn')||name.endsWith('.bsp')||name.startsWith('_fb0x')||name==='data_0.pak'||name==='zanthp.exe')state.files.set(name,f)}
 if(autoPak)state.files.set('data_0.pak',autoPak);
 const fbs=state.files.get('_fb0x05.fbs');if(!fbs){status('<b>Ошибка:</b> _fb0x05.fbs не найден.');return}
 try{
   state.pak=state.files.get('data_0.pak')||state.externalPak||null;
   for(const [name,f] of state.files){if(/^_fb0x[0-9a-f]{2}\.fbs$/i.test(name)){try{state.dbs.set(name,ZEE.parseDatabase(new Uint8Array(await f.arrayBuffer())))}catch(e){console.warn('Не удалось прочитать '+name,e)}}}
   state.db=state.dbs.get('_fb0x05.fbs')||ZEE.parseDatabase(new Uint8Array(await fbs.arrayBuffer()));state.dbs.set('_fb0x05.fbs',state.db);
   state.dialogDb=state.dbs.get('_fb0x06.fbs')||null;
   state.catalog=ZEE.buildNpcCatalog(state.db).sort((a,b)=>a.name.localeCompare(b.name));for(const [name,f] of state.files)if(name.endsWith('.scn'))state.scenes.set(name,f);
   renderNpcSelect();renderEnemyTemplates();renderEnemyDialogs();renderEnemyGroupEditors();renderItemSelect();renderSceneList();const gameExe=state.files.get('zanthp.exe');if(gameExe)loadExeFile(gameExe);
   $('saveFbs').disabled=false;$('saveDialogFbs').disabled=!state.dialogDb;$('applyTeam').disabled=false;$('overwriteGame').disabled=!state.canWriteGame;
   status(`Загружено: <b>${state.catalog.length}</b> NPC, <b>${state.scenes.size}</b> сцен. ${state.dialogDb?'Диалоги <b>_fb0x06</b> загружены — стандартные реплики показаны текстом. ':''}${state.pak?'Найден <b>data_0.pak</b> — доступен 3D-предпросмотр actor/DFF.':'Для настоящего 3D-предпросмотра внешности добавьте data_0.pak.'}`);
 }catch(e){status('<b>Ошибка чтения:</b> '+e.message);console.error(e)}
}
function renderNpcSelect(){const s=$('npcSelect');s.innerHTML='';for(const n of state.catalog.filter(x=>!x.isWildEnemyProfile)){const o=document.createElement('option');o.value=n.index;o.textContent=`${n.name} — ${ZEE.hex32(n.uid)}`;s.appendChild(o)}if(state.catalog.length){s.value=state.catalog[0].index;showNpc(state.catalog[0])}}
function renderEnemyTemplates(){
 const sel=$('enemyTemplate');if(!sel)return;sel.innerHTML='';const seen=new Set(),list=[];
 for(const n of state.catalog.filter(x=>!x.isWildEnemyProfile&&!x.isCustomVisibleEnemy)){const code=ZEE.appearanceCodeFromEntry(n.entry);if(!code||seen.has(code.toLowerCase()))continue;seen.add(code.toLowerCase());list.push(n)}
 list.sort((a,b)=>a.name.localeCompare(b.name));for(const n of list){const code=ZEE.appearanceCodeFromEntry(n.entry),o=document.createElement('option');o.value=n.index;o.textContent=`${n.name} · C.${code}`;sel.appendChild(o)}
 const pref=list.find(n=>ZEE.appearanceCodeFromEntry(n.entry)==='u003s03m')||list.find(n=>n.name==='nq4001')||list[0];if(pref)sel.value=String(pref.index);renderEnemyAppearanceInfo();renderEnemyDialogs()
}
function battleTemplate(){return state.catalog.find(n=>n.name==='nq4001'&&n.isBattleReadyEnemy)||state.catalog.find(n=>n.isBattleReadyEnemy&&!n.isCustomVisibleEnemy)||state.catalog.find(n=>n.isBattleReadyEnemy)}
function dbEntryByUid(uid){for(const [name,db] of state.dbs){const e=db.entries.find(x=>(x.uid>>>0)===(uid>>>0));if(e)return{name,db,entry:e}}return null}
async function ensureEnemyPreview(){if(state.enemyPreview)return state.enemyPreview;const a=$('enemyPreviewWorld'),b=$('enemyPreviewOverlay');if(!a||!b)return null;state.enemyPreview=new ZBSP.Viewer(a,b);state.enemyPreview.setPoints([],null);return state.enemyPreview}
async function renderEnemyAppearanceInfo(){
 const n=state.catalog.find(x=>x.index===+$('enemyTemplate')?.value),box=$('enemyAppearanceInfo');if(!box)return;if(!n){box.textContent='Нет доступного боевого шаблона.';return}
 const code=ZEE.appearanceCodeFromEntry(n.entry),same=state.view?.placements?.filter(p=>p.npc&&ZEE.appearanceCodeFromEntry(p.npc.entry)===code)||[];
 box.innerHTML=`Профиль <b>${n.name}</b> · игровая команда внешности <b>C.${code||'?'}</b>.${same.length?` На текущей сцене найдено ${same.length} NPC с тем же C-кодом.`:''}`;await refreshEnemyPreview();
}
async function refreshEnemyPreview(){
 const n=state.catalog.find(x=>x.index===+$('enemyTemplate')?.value),pv=await ensureEnemyPreview();if(!pv||!n)return;const code=ZEE.appearanceCodeFromEntry(n.entry),box=$('enemyAppearanceInfo');if(!state.pak){pv.geo=null;pv.draw();box.innerHTML+=`<br>Для реальной модели C.${code||'?'} нужен data_0.pak.`;return}
 try{const r=await ZBSP.dffFromAppearanceCode(state.pak,code),geo=ZBSP.parseDFF(r.bytes);pv.setGeometry(geo);pv.setPoints([],null);pv.reset();let tx={loaded:0,total:0};try{tx=await pv.loadTexturesFromPak(state.pak)}catch(te){console.warn('Enemy textures',te)}box.innerHTML+=`<br><b>3D-предпросмотр:</b> ${r.source} · ${geo.tris} треуг.${tx.total?` · текстуры ${tx.loaded}/${tx.total}`:' · DFF без распознанных материалов/текстур'}`}catch(e){console.warn('DFF preview',e);box.innerHTML+=`<br>3D: ${e.message}`;pv.geo=null;pv.draw()}
}
function renderEnemyDialogs(){
 const sel=$('enemyDialog');if(!sel)return;const keep=sel.value;sel.innerHTML='';const t=battleTemplate();const inherited=t?ZEE.attackDialogUidFromEntry(t.entry):null;
 const add=(val,label)=>{const o=document.createElement('option');o.value=val;o.textContent=label;sel.appendChild(o)};add('inherit',inherited?`Как у шаблона — ${dialogLabel(inherited)}`:'Как у шаблона');
 const seen=new Set();for(const n of state.catalog.filter(x=>x.isBattleReadyEnemy)){const uid=ZEE.attackDialogUidFromEntry(n.entry);if(uid==null||seen.has(uid))continue;seen.add(uid);add('uid:'+uid,dialogLabel(uid))}
 if([...sel.options].some(o=>o.value===keep))sel.value=keep;else sel.value='inherit';updateEnemyDialogUi()
}
function dialogLabel(uid){const text=state.dialogDb?ZEE.dialogTextByUid(state.dialogDb,uid):'';return text?`${text.replace(/\s+/g,' ').slice(0,90)} · [${ZEE.hex32(uid)}]`:`Реплика UID ${ZEE.hex32(uid)}`}
function updateEnemyDialogUi(){const w=$('enemyCustomDialogWrap');if(w)w.hidden=true}
function renderItemSelect(){const s=$('itemSelect');s.innerHTML='';for(const it of ZEE.ITEMS){const o=document.createElement('option');o.value=it.id;o.textContent=`${it.id}: ${it.name}`;s.appendChild(o)}s.value='4'}
function renderSceneList(){const q=$('sceneSearch').value.toLowerCase(),box=$('sceneList');box.innerHTML='';for(const name of [...state.scenes.keys()].sort()){if(q&&!name.includes(q))continue;const b=document.createElement('button');b.textContent=name;b.className=name===state.sceneName?'active':'';const c=state._counts.get(name);if(c){const sm=document.createElement('small');sm.textContent=`${c.npc} NPC · ${c.items} предм. · ${c.wild||0} диких`;b.appendChild(sm)}b.onclick=()=>openScene(name);box.appendChild(b)}}
async function openScene(name){try{const f=state.scenes.get(name);state.sceneBytes=new Uint8Array(await f.arrayBuffer());state.sceneName=name;state.sceneDirty=false;state.undoByScene.set(name,[]);cancelPlace();refreshScene();renderSceneList();updateUndoButton();await loadBspForScene(name)}catch(e){alert('Не удалось открыть сцену: '+e.message);console.error(e)}}
async function loadBspForScene(name){
  $('bspInfo').textContent='Загрузка BSP…';
  try{
    let bytes;
    const misc=state.sceneBytes?ZEE.parseMisc(state.sceneBytes):null;
    const internal=(misc&&misc.sceneFile?misc.sceneFile:'').replace(/\0+$/,'').trim();
    const baseFromFile=name.replace(/\.scn$/i,'');
    const candidates=[internal,baseFromFile].filter(Boolean).map(x=>String(x).replace(/\\/g,'/').split('/').pop().replace(/\.(?:scn|bsp)$/i,''));
    const unique=[...new Set(candidates.map(x=>x.toLowerCase()))];
    const directEntry=[...state.files.entries()].find(([k])=>unique.some(b=>k.toLowerCase()===b+'.bsp'));
    if(directEntry) bytes=new Uint8Array(await directEntry[1].arrayBuffer());
    else if(state.pak){
      let lastErr=null;
      for(const candidate of candidates){
        try{bytes=await ZBSP.bspFromPak(state.pak,candidate);break}catch(e){lastErr=e}
      }
      if(!bytes) throw lastErr||new Error('BSP не найден в PAK');
    } else throw new Error('нет BSP/data_0.pak');
    state.bsp=ZBSP.parseBSP(bytes);if(!state.viewer)state.viewer=new ZBSP.Viewer($('worldCanvas'),$('mapCanvas'));configureViewerPointDrag();state.viewer.setGeometry(state.bsp);drawMap();
    let texInfo='';
    if(state.pak){
      $('bspInfo').textContent='BSP загружен · загрузка текстур…';
      try{const ts=await state.viewer.loadTexturesFromPak(state.pak);texInfo=ts.total?` · текстуры ${ts.loaded}/${ts.total}`:''}catch(te){console.warn('Texture loading failed',te);texInfo=' · текстуры недоступны'}
    }
    $('bspInfo').textContent=`${state.bsp.sectors} сект. · ${state.bsp.tris} треуг.${texInfo}${internal&&internal.toLowerCase()!==baseFromFile.toLowerCase()?' · '+internal:''}`;status(`<b>${name}</b>: BSP загружена${texInfo?'; '+texInfo.replace(/^ · /,''):''}. Голубые — NPC, зелёные — предметы, розовые области — реальные радиусы нападения диких фей.`)}catch(e){state.bsp=null;$('bspInfo').textContent='BSP недоступен: '+e.message;console.warn(e);status(`<b>${name}:</b> 3D-карта не загружена — ${e.message}. Если data_0.pak лежит отдельно, нажмите «Выбрать data_0.pak».`);drawMap()}}
function refreshScene(){try{const nv=ZEE.placementsFromScene(state.sceneBytes,state.catalog),iv=ZEE.itemsFromScene(state.sceneBytes),wv=ZEE.wildFromScene(state.sceneBytes,state.catalog);state.view={...nv,placements:nv.placements,items:iv.items,wilds:wv.wilds,itemSections:iv,wildSections:wv};state._counts.set(state.sceneName,{npc:nv.placements.length,items:iv.items.length,wild:wv.wilds.length});$('sceneTitle').textContent=state.sceneName;$('sceneInfo').textContent=`${nv.placements.length} NPC · ${iv.items.length} предметов · ${wv.wilds.length} мест диких фей`;state.selected=null;$('saveScn').disabled=false;$('placeNpcBtn').disabled=false;$('placeItemBtn').disabled=false;$('placeWildBtn').disabled=false;$('addItemCoords').disabled=false;$('addWildCoords').disabled=false;$('deleteBtn').disabled=true;$('applyPlacement').disabled=true;$('deleteItem').disabled=true;$('applyItem').disabled=true;$('deleteWild').disabled=true;$('applyWild').disabled=true;drawMap();renderEnemyAppearanceInfo();updateDebug();renderSceneList()}catch(e){status(`<b>${state.sceneName}:</b> ${e.message}`);console.error(e)}}

function undoStack(){if(!state.sceneName)return[];if(!state.undoByScene.has(state.sceneName))state.undoByScene.set(state.sceneName,[]);return state.undoByScene.get(state.sceneName)}
function updateUndoButton(){const b=$('undoAdd');if(!b)return;const st=undoStack();b.disabled=!state.sceneBytes||!st.length;b.title=st.length?`Отменить: ${st[st.length-1].label} (Ctrl+Z)`:'Нет добавлений для отмены'}
function rememberBeforeAdd(label){if(!state.sceneBytes||!state.sceneName)return;const st=undoStack();st.push({bytes:state.sceneBytes.slice(),label});if(st.length>50)st.shift();updateUndoButton()}
function undoLastAdd(){const st=undoStack();if(!st.length||!state.sceneBytes)return;const a=st.pop();state.sceneBytes=a.bytes;state.sceneDirty=true;cancelPlace();refreshScene();updateUndoButton();status(`Отменено: <b>${a.label}</b>.`)}

function currentNpc(){return state.catalog.find(n=>n.index===+$('npcSelect').value)}
function addNewEnemyAt(pos){
 const pending=state.pendingNewEnemy;if(!pending)throw new Error('Не подготовлен новый враг.');const appearance=state.catalog.find(n=>n.index===pending.appearanceIndex),template=battleTemplate();if(!appearance)throw new Error('Выбранная внешность больше не доступна.');if(!template)throw new Error('Не найден рабочий боевой шаблон.');const appearanceCode=ZEE.appearanceCodeFromEntry(appearance.entry);rememberBeforeAdd(`добавление нового врага C.${appearanceCode}`);
 const created=ZEE.cloneNpcProfile(state.db,template.entry,pending.team,'_CustomElf_');ZEE.setAppearanceCode(created.entry,appearanceCode);let dialogUid=ZEE.attackDialogUidFromEntry(template.entry);
 if(pending.dialogMode==='existing'){dialogUid=pending.dialogUid;ZEE.setAttackDialogUid(created.entry,dialogUid)}

 state.catalog=ZEE.buildNpcCatalog(state.db).sort((a,b)=>a.name.localeCompare(b.name));renderNpcSelect();renderEnemyTemplates();const npc=state.catalog.find(n=>n.uid===created.uid);if(!npc)throw new Error('Новый профиль создан, но не найден после перечитывания каталога.');const proto=state.view?.placements.find(x=>x.npc?.name==='nq4001'&&x.trigger.type===1)?.trigger||state.view?.placements.find(x=>x.trigger.type===1&&x.trigger.ii===3)?.trigger||state.view?.placements[0]?.trigger;state.sceneBytes=ZEE.addPlacement(state.sceneBytes,npc,pos,proto,pending.radius,null);state.sceneDirty=true;state.fbsDirty=true;state.pendingNewEnemy=null;refreshScene();const p=state.view.placements.filter(x=>x.npc?.uid===npc.uid).pop();if(p)selectEntity(p);status(`Создан <b>${npc.name}</b> · внешность C.${appearanceCode} (${appearance.name}) · реплика ${dialogUid!=null?ZEE.hex32(dialogUid):'шаблон'} · radius ${pending.radius.toFixed(2)}.`)
}
function nextCustomGroupId(){
 const used=new Set();
 for(const n of state.catalog||[]){const m=String(n.name||'').match(/^_CustomGroup(\d+)_/i);if(m)used.add(+m[1]);}
 for(let i=1;i<1000;i++)if(!used.has(i))return i;
 throw new Error('Не удалось подобрать номер новой группы.');
}
function setInternalProfileName(entry,name){const f=ZEE.fieldByColumn(entry,19);if(!f)throw new Error('У профиля нет internal-name поля');f._modifiedString=name;}
function addNewEnemyGroupAt(pos){
 const pending=state.pendingEnemyGroup;if(!pending)throw new Error('Не подготовлена группа врагов.');
 const leaderTemplate=battleTemplate();if(!leaderTemplate)throw new Error('Не найден рабочий боевой шаблон nq4001.');
 const supportTemplate=state.catalog.find(n=>n.name==='ns321a');if(!supportTemplate)throw new Error('Для v0.8.26 нужен оригинальный ns321a из sc_0611.');
 rememberBeforeAdd(`физическая группа sc_0611 из ${pending.members.length} врагов`);
 const created=[],groupId=nextCustomGroupId(),groupTag=String(groupId).padStart(2,'0');
 for(let i=0;i<pending.members.length;i++){
  const m=pending.members[i],appearance=state.catalog.find(n=>n.index===m.appearanceIndex);if(!appearance)throw new Error(`Внешность противника ${i+1} больше не доступна.`);
  const code=ZEE.appearanceCodeFromEntry(appearance.entry),base=i===0?leaderTemplate.entry:supportTemplate.entry,c=ZEE.cloneNpcProfile(state.db,base,m.team,'_CustomEnemy_');
  const groupName=i===0?`_CustomGroup${groupTag}_Leader`:`_CustomGroup${groupTag}_Support${String(i).padStart(2,'0')}`;
  setInternalProfileName(c.entry,groupName);c.name=groupName;
  ZEE.setAppearanceCode(c.entry,code);if(i===0&&pending.dialogUid!=null)ZEE.setAttackDialogUid(c.entry,pending.dialogUid);created.push({raw:c,code,appearance});
 }
 state.catalog=ZEE.buildNpcCatalog(state.db).sort((a,b)=>a.name.localeCompare(b.name));renderNpcSelect();renderEnemyTemplates();renderEnemyGroupEditors();const npcs=created.map(c=>state.catalog.find(n=>n.uid===c.raw.uid));if(npcs.some(x=>!x))throw new Error('Не удалось перечитать один из созданных профилей группы.');
 const proto=state.view?.placements.find(x=>x.npc?.name==='nq4001'&&x.trigger.type===1)?.trigger||state.view?.placements.find(x=>x.trigger.type===1&&x.trigger.ii===3)?.trigger||state.view?.placements[0]?.trigger;
 state.sceneBytes=ZEE.addPlacement(state.sceneBytes,npcs[0],pos,proto,pending.radius,null);
 const links=[],supportIds=[],count=npcs.length,ring=3.0;
 for(let i=1;i<count;i++){
  const a=(i-1)*Math.PI*2/Math.max(1,count-1),x=pos.x+Math.cos(a)*ring,z=pos.z+Math.sin(a)*ring,ground=state.viewer?.terrainHeightAt?.(x,z,pos.y),physical={x,y:Number.isFinite(ground)?ground:pos.y,z};
  // Marker is intentionally co-located with the physical support. P still gets the exact sc_0611 ii=5 architecture,
  // but it no longer asks the actor/camera choreography to jump to a second remote point.
  const marker={...physical};
  const r=ZEE.addLinkedGroupSupport(state.sceneBytes,npcs[i],physical,marker,{x:-Math.cos(a),y:-0.2,z:-Math.sin(a)});state.sceneBytes=r.bytes;links.push({markerIdx:r.markerIdx,uid:npcs[i].uid});supportIds.push(r.npcIdx);
 }
 ZEE.setLinkedGroupScript(npcs[0].entry,links);
 ZEE.setLinkedGroupCleanup(npcs[0].entry,supportIds);
 state.sceneDirty=true;state.fbsDirty=true;state.pendingEnemyGroup=null;refreshScene();const leader=state.view.placements.filter(x=>x.npc?.uid===npcs[0].uid).pop();if(leader)selectEntity(leader);status(`Создана группа <b>Group ${groupTag}</b> из <b>${npcs.length}</b>: физические supports ii=3/ii2=3, P→ii=5 markers и post-battle cleanup ${supportIds.map(x=>`a.${x}`).join(' · ')}.`)
}
function currentItem(){return ZEE.ITEMS.find(x=>x.id===+$('itemSelect').value)}
