function readDeckVariants(){const count=Math.max(1,Math.min(5,+$('deckVariantCount').value||1)),out=[];for(let vi=0;vi<count;vi++){const team=[];for(let slot=0;slot<5;slot++){const q=document.querySelector(`[data-vfairy="${vi}-${slot}"]`),l=document.querySelector(`[data-vlevel="${vi}-${slot}"]`);if(q&&q.value!=='')team.push({slot,fairyId:+q.value,level:Math.max(1,Math.min(99,+l.value||1))})}if(!team.length)throw new Error(`Вариант ${vi+1} пустой.`);out.push(team)}return out}
