function renderEnemyGroupEditors(){const box=$('enemyGroupEditors');if(!box)return;const count=Math.max(2,Math.min(5,+$('enemyGroupCount')?.value||2)),apps=enemyAppearanceList(),preferred=apps.find(n=>ZEE.appearanceCodeFromEntry(n.entry)==='u003s03m')||apps[0];box.innerHTML='';for(let gi=0;gi<count;gi++){const d=document.createElement('div');d.className='groupenemy'+(gi===0?' leader':'');d.innerHTML=`<h4>Противник ${gi+1}${gi===0?'<span class="groupbadge">лидер</span>':'<span class="groupbadge">support</span>'}</h4><label>Внешность<select data-gappearance="${gi}"></select></label><div class="groupteam" data-gteam="${gi}"></div>`;box.appendChild(d);const as=d.querySelector(`[data-gappearance="${gi}"]`);for(const n of apps){const o=document.createElement('option');o.value=n.index;o.textContent=`${n.name} · C.${ZEE.appearanceCodeFromEntry(n.entry)}`;as.appendChild(o)}if(preferred)as.value=String(preferred.index);const tb=d.querySelector(`[data-gteam="${gi}"]`);for(let slot=0;slot<5;slot++){const row=document.createElement('div');row.className='teamrow';row.innerHTML=`<div class="slot">${slot+1}</div><label>Фея<select data-gfairy="${gi}-${slot}"><option value="">— нет —</option></select></label><label>Уровень<input data-glevel="${gi}-${slot}" type="number" min="1" max="99" value="${Math.min(99,10+gi*10+slot)}"></label>`;tb.appendChild(row);fillFairySelect(row.querySelector('select'),null)}}}
