function populateCustomPoolUI(){
  const ps=$('customPoolId');ps.innerHTML='';for(const id of ZEE.CUSTOM_POOL_IDS){const o=document.createElement('option');o.value=id;o.textContent=`Pool ${id}`;ps.appendChild(o)}
  const lr=$('customLevelRange');lr.innerHTML='';for(let m=5;m<=80;m++){const o=document.createElement('option');o.value=m;o.textContent=`${ZEE.wildLevelRange(m)} уровень`;lr.appendChild(o)}
  const rows=$('customRows');rows.innerHTML='';for(let i=0;i<6;i++){const d=document.createElement('div');d.className='customrow';d.innerHTML=`<label>Фея ${i+1}<select data-cfairy="${i}"></select></label><label>Вес<input data-cweight="${i}" type="number" min="0" max="8" step="1" value="0"></label>`;rows.appendChild(d);const sel=d.querySelector('select');for(const f of ZEE.FAIRIES){const o=document.createElement('option');o.value=f.id;o.textContent=`${f.id}: ${f.name}`;sel.appendChild(o)}}
  ps.value='34';showCustomPoolEditor();
}
function showCustomPoolEditor(){const id=+$('customPoolId').value,cfg=state.customPools.find(x=>x.id===id)||{id,enabled:false,levelParam:5,slots:[0]};$('customEnabled').checked=cfg.enabled;$('customLevelRange').value=String(cfg.levelParam);$('customLevelMode').value=cfg.manualMin!=null?'manual':'preset';$('customMinLevel').value=cfg.manualMin??10;$('customMaxLevel').value=cfg.manualMax??15;$('customPresetWrap').hidden=$('customLevelMode').value==='manual';$('customManualWrap').hidden=$('customLevelMode').value!=='manual';const counts=new Map();for(const f of cfg.slots)counts.set(f,(counts.get(f)||0)+1);const entries=[...counts.entries()];for(let i=0;i<6;i++){const e=entries[i];const sel=document.querySelector(`[data-cfairy="${i}"]`),w=document.querySelector(`[data-cweight="${i}"]`);sel.value=String(e?.[0]??ZEE.FAIRIES[0].id);w.value=e?.[1]??0}renderCustomPreview()}
function readCustomEditor(){const id=+$('customPoolId').value,enabled=$('customEnabled').checked,levelParam=Math.max(5,Math.min(80,+$('customLevelRange').value||5));let manualMin=null,manualMax=null;if($('customLevelMode').value==='manual'){manualMin=Math.max(1,Math.min(99,+$('customMinLevel').value||1));manualMax=Math.max(1,Math.min(99,+$('customMaxLevel').value||manualMin));if(manualMax<manualMin)[manualMin,manualMax]=[manualMax,manualMin];}const slots=[];for(let i=0;i<6;i++){const idv=+document.querySelector(`[data-cfairy="${i}"]`).value,w=Math.max(0,Math.min(8,+document.querySelector(`[data-cweight="${i}"]`).value||0));for(let j=0;j<w;j++)slots.push(idv)}if(slots.length>8)throw new Error(`Сумма весов ${slots.length}. Максимум — 8.`);if(enabled&&!slots.length)throw new Error('У активного кастомного пула должна быть хотя бы одна фея.');return {id,enabled,levelParam,slots:slots.length?slots:[0],manualMin,manualMax}}
function renderCustomPreview(){let cfg;try{cfg=readCustomEditor()}catch(e){$('customPoolPreview').textContent=e.message;return}$('customLevelInfo').innerHTML=cfg.manualMin!=null?`При размещении этого пула с ручным режимом будет создан _fb0x05-профиль с точным диапазоном <b>${cfg.manualMin}–${cfg.manualMax}</b>. Сам EXE-пул сохраняет готовый параметр ${ZEE.wildLevelRange(cfg.levelParam)}.`:`В игре будут появляться феи уровня <b>${ZEE.wildLevelRange(cfg.levelParam)}</b>.`;const counts=new Map();for(const id of cfg.slots)counts.set(id,(counts.get(id)||0)+1);$('customPoolPreview').innerHTML=[...counts].map(([id,n])=>`${ZEE.FAIRY_BY_ID.get(id)?.name||('Fairy '+id)} — <b>${(n/cfg.slots.length*100).toFixed((100*n/cfg.slots.length)%1?1:0)}%</b>`).join(' · ')+`<br>raw slots: [${cfg.slots.join(', ')}]`}
async function loadExeFile(f){try{const bytes=new Uint8Array(await f.arrayBuffer());state.exeFile=f;state.exeBytes=bytes;const patched=ZEE.hasCustomPoolPatch(bytes),orig=ZEE.isOriginalZanthp(bytes);if(patched){const cfg=ZEE.readZanthpCustomPools(bytes);if(cfg)state.customPools=cfg;$('exeStatus').innerHTML=`Загружен <b>${f.name}</b>: найден патч Custom Pools v${ZEE.customPatchVersion(bytes)}.`;renderWildSelect();showCustomPoolEditor()}else if(orig){$('exeStatus').innerHTML=`Загружен поддерживаемый оригинальный <b>${f.name}</b>.`;}else{$('exeStatus').innerHTML=`<b>Внимание:</b> ${f.name} не совпадает с поддерживаемой версией zanthp.exe.`}$('patchExe').disabled=!(orig||patched)}catch(e){$('exeStatus').textContent='Ошибка чтения EXE: '+e.message;$('patchExe').disabled=true}}
