$('customPoolId').onchange=showCustomPoolEditor;$('customEnabled').onchange=renderCustomPreview;$('customLevelRange').onchange=renderCustomPreview;$('customLevelMode').onchange=()=>{$('customPresetWrap').hidden=$('customLevelMode').value==='manual';$('customManualWrap').hidden=$('customLevelMode').value!=='manual';renderCustomPreview()};$('customMinLevel').oninput=renderCustomPreview;$('customMaxLevel').oninput=renderCustomPreview;$('customRows').addEventListener('input',renderCustomPreview);$('customRows').addEventListener('change',renderCustomPreview);
